-- ════════════════════════════════════════════════════════════════════════════
-- DANGER: deletes ALL app tables and data (demo only) — generated by `pnpm db:build-setup`.
-- Paste into Supabase SQL Editor and Run, then run db/setup.sql again.
-- Does not touch anything else in the database. The clinic_app login is kept
-- (setup.sql just sets its password again).
-- ════════════════════════════════════════════════════════════════════════════
begin;
do $guard$
declare
  has_fake boolean;
  has_demo boolean;
  real_count int := 0;
begin
  if to_regclass('public.patients') is null or to_regclass('public.tenants') is null then
    return;
  end if;
  select exists (select from information_schema.columns where table_schema = 'public'
                   and table_name = 'patients' and column_name = 'is_fake') into has_fake;
  select exists (select from information_schema.columns where table_schema = 'public'
                   and table_name = 'tenants' and column_name = 'is_demo') into has_demo;
  if not has_fake and not has_demo then
    return;
  end if;
  execute 'alter table public.patients no force row level security';
  execute 'alter table public.tenants no force row level security';
  execute 'select count(*) from public.patients p join public.tenants t on t.id = p.tenant_id where '
    || case when has_fake then 'not p.is_fake' else 'false' end
    || case when has_demo then ' or not t.is_demo' else '' end
    into real_count;
  if real_count > 0 then
    raise exception 'REFUSED: this database holds % real patient record(s). db/reset.sql is for the demo only and would delete them. Use a numbered db/upgrades file instead.', real_count;
  end if;
end
$guard$;
drop table if exists
  public.accounts,
  public.appointments,
  public.audit_logs,
  public.billing_items,
  public.branch_holidays,
  public.branches,
  public.care_team,
  public.clinical_note_addenda,
  public.clinical_notes,
  public.concern_events,
  public.consent_rules,
  public.consent_templates,
  public.conversations,
  public.dental_chart_entries,
  public.dental_plan_items,
  public.departments,
  public.devices,
  public.files,
  public.global_rate_hits,
  public.lab_cases,
  public.message_dispatches,
  public.message_templates,
  public.messages,
  public.notification_prefs,
  public.outbound_messages,
  public.package_payments,
  public.package_session_events,
  public.package_templates,
  public.patient_consents,
  public.patient_medical_flags,
  public.patient_packages,
  public.patient_sessions,
  public.patients,
  public.platform_payments,
  public.platform_statements,
  public.push_log,
  public.push_subscriptions,
  public.rate_limit_hits,
  public.reschedule_requests,
  public.reservations,
  public.rooms,
  public.schedule_exceptions,
  public.service_practitioners,
  public.services,
  public.sessions,
  public.staff_schedules,
  public.support_grants,
  public.tenant_members,
  public.tenant_settings,
  public.tenants,
  public.time_blocks,
  public.two_factors,
  public.users,
  public.verification_codes,
  public.verifications,
  public.visit_charges,
  public.visit_checkouts,
  public.visit_orders,
  public.webhook_events
  cascade;
drop function if exists public.app_assists;
drop function if exists public.app_billing_enforce;
drop function if exists public.app_branch_allowed;
drop function if exists public.app_create_clinic;
drop function if exists public.app_current_tenant;
drop function if exists public.app_current_user;
drop function if exists public.app_has_role;
drop function if exists public.app_is_patient;
drop function if exists public.app_is_platform_owner;
drop function if exists public.app_patient;
drop function if exists public.app_patient_scope;
drop function if exists public.app_platform_gate;
drop function if exists public.app_set_clinic_limits;
drop function if exists public.app_set_clinic_plan;
drop function if exists public.app_set_clinic_status;
drop function if exists public.app_set_clinic_whatsapp;
drop function if exists public.app_visit_completed;
drop function if exists public.app_visit_open;
drop function if exists public.apply_package_session_event;
drop function if exists public.demo_workday;
drop function if exists public.guard_clinical_note;
drop function if exists public.guard_note_addendum;
drop function if exists public.guard_package_balance;
drop function if exists public.normalize_search;
drop function if exists public.sync_appointment_reservations;
drop function if exists public.sync_time_block_reservations;
-- Types last: functions may use them (e.g. app_set_clinic_status takes a clinic_status).
drop type if exists public.appointment_status, public.billing_item_kind, public.booking_source, public.clinic_status, public.dental_plan_status, public.gender, public.id_type, public.lab_case_status, public.lab_work, public.medical_flag_kind, public.member_role, public.note_status, public.payment_method, public.plan_tier, public.request_status, public.session_event_kind, public.statement_status, public.tooth_condition, public.visit_order_kind;
do $$
begin
  if exists (select from pg_roles where rolname = 'clinic_app') then
    execute 'revoke all on schema public from clinic_app';
  end if;
end $$;
commit;
select 'Reset complete. Now run db/setup.sql.' as result;
